from .units import to_grams


class Item:
    """One order line.

    Fields (validate_item reads this table, keep it in sync):
        sku: str, 1..32
        weight_g: int, 1..1000000
        qty: int, 1..1000
    """

    def __init__(self, sku, weight_g, qty=1):
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 1:
            raise ValueError(f"invalid quantity: {qty!r}")
        self.sku = sku
        self.weight_g = to_grams(weight_g)
        self.qty = qty

    def line_weight_g(self):
        return self.weight_g * self.qty

    def to_dict(self):
        return {"sku": self.sku, "weight_g": self.weight_g, "qty": self.qty}

    @classmethod
    def from_dict(cls, data):
        return cls(data["sku"], data["weight_g"], data.get("qty", 1))


class Order:
    def __init__(self, items=()):
        self.items = list(items)

    def add(self, item):
        self.items.append(item)

==> shipcalc/packing.py <==
MAX_PARCEL_G = 20000


class Parcel:
    def __init__(self, weight_g, skus):
        self.weight_g = weight_g
        self.skus = list(skus)

    def add(self, weight_g, sku):
        self.weight_g += weight_g
        self.skus.append(sku)


def split_parcels(order):
    """First-fit decreasing. A unit heavier than the limit travels alone."""
    units = []
    for item in order.items:
        units.extend((item.weight_g, item.sku) for _ in range(item.qty))
    units.sort(key=lambda unit: (-unit[0], unit[1]))
    parcels = []
    for grams, sku in units:
        for parcel in parcels:
            if parcel.weight_g + grams <= MAX_PARCEL_G:
                parcel.add(grams, sku)
                break
        else:
            parcels.append(Parcel(grams, [sku]))
    return parcels

==> shipcalc/rates.py <==
ZONES = {"eu": (400, 90), "us": (900, 150), "world": (1500, 260)}  # (base cents, cents per extra step)
STEP_G = 500
HEAVY_G = 10000
HEAVY_SURCHARGE = 500


def shipping_cents(weight_g, zone):
    try:
        base, per_step = ZONES[zone]
    except KeyError:
        raise ValueError(f"unknown zone: {zone!r}") from None
    steps = max(1, -(-weight_g // STEP_G))
    cents = base + per_step * (steps - 1)
    if weight_g > HEAVY_G:
        cents += HEAVY_SURCHARGE
    return cents

